from collections import defaultdict

def find_cycle_length(n, m, edges):
    # Create an adjacency list for graph representation
    graph = defaultdict(list)
    for i, j, c1, c2 in edges:
        graph[i].append((j, c1))
        graph[j].append((i, c2))

    visited = [False] * n
    num_cycles = set()

    def dfs(node, parent):
        if visited[node]:
            if node == parent:
                return
            # Get the cycle complete
            cycle = []
            while node != parent:
                cycle.append(node)
                node = node[0]  # Back to the current parent node
            cycle.reverse()
            num_cycles.add(tuple(cycle))
            return
        visited[node] = True
        for neighbor, cost in graph[node]:
            if neighbor == parent:
                continue
            if cost > 0:
                dfs(values[neighbor], node)
            else:
                dfs(neighbor, node)
        visited[node] = False

    values = [None] * n
    for node in range(n):
        if not visited[node]:
            dfs(node, -1)

    return len(min(num_cycles, key=len))

