def extended_gcd(a, b: int) -> Tuple[int, int, int]:
    """Extended Euclidean Algorithm to find the coefficients x and y of Bezout's identity."""
    if a == 0:
        return (b, 0, 1)
    g, y, x = extended_gcd(b % a, a)
    return (g, x - (b // a) * y, y)

