    """Evaluate C(n, 0) C(n, 1) ... C(n, n) modulo mod."""
    return factorial_modulo(n, mod) * (lcm(mod, factorial_modulo(mod, mod)) // factorial_modulo(2 * mod, mod)) % mod

def hfactors(n: int) -> list:
    """Return the Co-Stirling numbers of the first kind as function of n."""
    numbers = [1, n]
    for k in range(2, n + 1):
