def is_equal_to_zero(a, n):
    xor_result = 0
    for i in range(1, n-1, 2):
        xor_result ^= a[i-1] ^ a[i] ^ a[i+1]
    return xor_result == 0

def find_op_to_modify_sequence_to_zeros(a, n):
    if is_equal_to_zero(a, n):
        return "YES\n1\n1\n1"

    min_operations = n
    for mid in range(1, n-1):
        if not is_equal_to_zero(a[::mid+1], mid+1):
            continue
        for start in range(1, n-mid):
            xor_result = 0
            seq = [1]
            for i in range(start, n-mid):
                xor_result ^= a[i]
                seq.append(i+mid)
            if xor_result == 0:
                return "YES\n" + " ".join(map(str, seq)) + "\n"
        for end in range(mid, 1, -1):
            xor_result = 0
            seq = [n-end+2]
            for i in range(end, n):
                xor_result ^= a[i]
                seq.append(i-n+end)
            if xor_result == 0:
