import sys

def find_initial_sequences(nums):
    n = len(nums)
    increasing = [True] * n
    decreasing = [True] * n
    increasing_indices = [-1] * n
    decreasing_indices = [-1] * n

    # Check prefix sums for increasing
    prefix_sum = 1
    for i in range(n):
        if nums[i] > nums[i-1] or (i > 0 and nums[i] < nums[i-1] and (increasing_indices[i-1] >= 0)):
            increasing[i] = False
        else:
            prefix_sum += 1
        if prefix_sum > 0:
            increasing_indices[i] = prefix_sum

    # Check prefix sums for decreasing
    postfix_sum = 1
    for i in range(n-1, -1, -1):
        if nums[i] < nums[i+1] or (i < n-1 and nums[i] > nums[i+1] and (decreasing_indices[i+1] >= 0)):
            decreasing[i] = False
        else:
            postfix_sum += 1
        if postfix_sum > 0:
            decreasing_indices[i] = postfix_sum

    # Form the solution
    res = [-1] * n
    for i in range(n):
        if (increasing[i] and decreasing_indices[i] >= 0) or (decreasing[i] and increasing_indices[i] >= 0):
            res[increasing_indices[i] - 1] = 0
            res[decreasing_indices[i]] = 0
            increasing_indices[i] = decreasing_indices[i] = -1
        if decreasing_indices[i] >= 0 and increasing_indices[i] >= 0:
            res[increasing_indices[i]-1] = 0
            res[decreasing_indices[i]] = 0
        if increasing_indices[i] < n and decreasing_indices[i] < n:
            res[increasing_indices[i]] = 0
            res[decreasing_indices[i]] = 0

    return res

