                mask[board[i][j]].append([i, j])

    # Find matching dominoes for each position on the board
    matches = []
    for domino in mask:
        matches.extend(mask[domino])

    # Sort matches to avoid permutations with same layout
    matches.sort()

    # Solve domino matching problem with backtracking
    stack = [(0, 0)]
    matched = [False] * (len(matches) + 1)
    sol = defaultdict(list)

    while stack:
        i, j = stack.pop()
        if i == len(matches):
            matches.append(matches.pop())
        else:
            if matched[i]:
                continue
            matched[i] = True
            if matches[i][0] in mask[matches[i][1]]:
                stack.append([i + 1, (matches[i][1], matches[i][0])])

    sol = matches[-1]

    total_permutations = 1
    for digit in '0123456':
        if digit in sol:
            total_permutations *= factorial(sol.count(digit))
        else:
            total_permutations //= factorial(sol.count(digit))

    return total_permutations


