import heapq

def min_box_difficulty(presents: List[List[int]]) -> int:
    n = len(presents)
    m = len(presents[0])

    intervals = [0] * m
    for i in range(n):
        for j in range(m):
            intervals[j] += 1 if j < m - 1 else -1 if j == m - 1 else 0

    sorted_intervals = [(i, j, intervals[i]) for i, j in enumerate(presents[0])]
    for i in range(1, n):
        x = len(sorted_intervals)
        for j in range(m):
            while j < x and intervals[j] >= intervals[j - 1]:
                j += 1
        sorted_intervals.insert(j, (sorted_intervals[i - 1][0] + 1, j))
        while j > 0 and intervals[j - 1] <= intervals[j]:
            j -= 1

    diff_bucket = []
    for i in range(len(presents)):
        min_diff = abs(presents[i][0] - i + 1)
        max_diff = abs(presents[i][0] - i + 1)
        for x in sorted_intervals[i]:
            min_diff = min(min_diff, x - i + 1)
            max_diff = max(max_diff, len(presents) - x - 1)
        heapq.heappush(diff_bucket, (min_diff, max_diff))

    total_moves = 0
    while diff_bucket:
        min_diff, max_diff = heapq.heappop(diff_bucket)
        total_moves += min_diff
        if min_diff > max_diff:
            diff_bucket.append((min_diff - max_diff, max_diff))

