from collections import deque

def tsp(moves, start, end):
    q = deque([([start], 0)])
    visited = {start}

    while q:
        path, cost = q.popleft()
        if path[-1] == end:
            return len(path) - 1
        for neighbor in neighbors[*(path[-1]), set(i+1 for i, _ in enumerate(path) if _ == start)]:
            if neighbor not in visited:
                visited.add(neighbor)
                q.append((path+[neighbor], cost+1))

    return -1

def move(moves, board, src, dest):
    steps = tsp(moves, src, dest)
    while steps >= 0:
        board[src[0]][src[1]] = 0
        board[dest[0]][dest[1]] = moves[-1]
        steps -= 1
        moves.pop()

