from heapq import heappush, heappop
from math import ceil, log2

# Define the functions to handle operations in the theoretical programming model
def partition(a, low, high):
    pivot = a[high]
    i = low - 1
    for j in range(low, high):
        if a[j] < pivot:
            i += 1
            a[i], a[j] = a[j], a[i]
    a[i + 1], a[high] = a[high], a[i + 1]
    return i + 1

def rPartition(a, low, high, pivot_point, max_pairs):
    pivot = a[pivot_point]
    stops = [j for j in range(high) if a[j] > pivot]
    if len(stops) < low or (max_pairs and a[low] > pivot):
        return low, high

    i = low - 1
    for j in range(low, high):
        if j < stops[0]:
            i += 1
            a[i], a[j] = a[j], a[i]
        else:
            a[i + 1], a[j] = a[j], a[i + 1]
            if a[j] == pivot:
                i += 1

    a[i + 1], a[stops[0]] = a[stops[0]], a[i + 1]
    piv = stops[0]
    return i + 1, piv

def randomizedPartition(a, low, high):
    return rPartition(a, low, high, ceil(log2(a.__len__()) * 1.2), False)[0]

def quickSelect(a, low, high, k):
    if low == high:
        return a[low]
    piv = randomizedPartition(a, low, high)
    if k < (piv + low) // 2:
        return quickSelect(a, low, piv - 1, k)
    elif k > (pivot_event + low) // 2:
        return quickSelect(a, piv + 1, high, k - ((pivot_event + low) // 2))
