from collections import deque

def can_fit_tasks(n, K, tables, formulas):
    table_stacks = deque()
    formula_stacks = deque()

    for i in range(n):
        page_state = (len(table_stacks), len(formula_stacks))

        if page_state > (K, K):
            return "NO"

        if page_state == (0, 0):
            page_state = (K, K)

        if page_state == (K, K):
            if i == n - 1 or table_stacks[-1][0] >= tables[i] + K or \
               formula_stacks[-1][0] >= formulas[i] + K:
                return "NO"

        if table_stacks and page_state[0] > K:
            if table_stacks[-1][0] >= tables[i] + K:
                return "NO"
            if formula_stacks:
                if formula_stacks[-1][0] >= formulas[i] + K:
                    return "NO"

        if page_state[0] == 0:
            table_stacks.appendleft((tables[i], i + K))
        else:
            table_stacks[i % K] = (tables[i] - table_stacks[i % K][0], i)

        if page_state[1] == 0:
            formula_stacks.appendleft((formulas[i], i + K))
        else:
            formula_stacks[i % K] = (formulas[i] - formula_stacks[i % K][0], i)

    if table_stacks and table_stacks[-1][0] >= tables[-1] + K:
        return "NO"
    if formula_stacks and formula_stacks[-1][0] >= formulas[-1] + K:
        return "NO"

    return "YES"

