            return "YES", moves, [i-2]
        if a[i-1] == a[i]:
            return "YES", moves, [i-3, i-2]
        moves += 2
    return "YES", moves, []

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        result = solve(n, a)
        print("YES" if result[0] == "YES" else "NO")
        if result[0] == "YES":
            print(result[1])
            print(result[2] if result[1] > 0 else "")

if __name__ == "__main__":
    main()
